def think(thought, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, hashlib, re

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate input
    if not isinstance(thought, str):
        return _err("VALIDATION_ERROR", "`thought` must be a string.")
    if thought == "":
        return _err("VALIDATION_ERROR", "`thought` must be non-empty.")
    if len(thought) > 20000:
        return _err("VALIDATION_ERROR", "`thought` exceeds maximum length (20000).")

    # Load data
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    thought_logs = _load("thought_logs.json")
    usage = _load("usage_counters.json")
    request_logs = _load("request_logs.json")  # optional collection

    # Ambient auth: select a workspace+key combination that can serve the call
    # Prefer an active, unexpired API key whose workspace is active; otherwise, allow workspace-only ambient auth
    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, str):
            try:
                return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
    ak_candidates = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not ws or ws.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and not (exp > now):
            continue
        ak_candidates.append((ws, k))

    chosen_ws = None
    chosen_key = None
    if ak_candidates:
        chosen_ws, chosen_key = ak_candidates[0]
    else:
        # workspace-only ambient: any active workspace
        for w in workspaces:
            if isinstance(w, dict) and w.get("status") == "active":
                chosen_ws = w
                chosen_key = None
                break

    endpoint = "think"
    cred_used = chosen_key.get("id") if chosen_key else None

    def _log_request(status_code, error_code=None):
        # Enforce quotas using usage_counters (not request_logs); request log is for observability.
        # Always append a request log row if the file exists or can be created.
        nonlocal request_logs
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256((now_iso + "|" + endpoint + "|" + str(cred_used) + "|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "workspace_id": chosen_ws.get("id") if chosen_ws else None,
            "api_key_id": cred_used,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now_iso,
        }
        if isinstance(request_logs, list):
            request_logs.append(row)
            _save("request_logs.json", request_logs)

    if not chosen_ws:
        _log_request(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated workspace context available for this call.")

    # Quota window: UTC day [midnight, next midnight)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    day_end = day_start + datetime.timedelta(days=1)
    day_start_iso = day_start.isoformat()
    day_end_iso = day_end.isoformat()

    def _find_usage_row(ws_id, api_key_id):
        for r in usage:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == ws_id and r.get("api_key_id") == api_key_id and r.get("window_start") == day_start_iso and r.get("window_end") == day_end_iso:
                return r
        return None

    # Workspace status must be active
    if chosen_ws.get("status") != "active":
        _log_request(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Idempotency key (not a tool parameter); supported via extra fields
    client_request_id = _extra.get("client_request_id")
    if client_request_id is not None and not isinstance(client_request_id, str):
        _log_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`client_request_id` must be a string when provided.")
    if isinstance(client_request_id, str) and client_request_id == "":
        _log_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`client_request_id` must be non-empty when provided.")

    # If idempotency key is provided, return existing row without creating a new one
    if isinstance(client_request_id, str):
        for r in thought_logs:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") == chosen_ws.get("id") and r.get("client_request_id") == client_request_id:
                # Still record request, but do not increment quotas (idempotent replay should not count again)
                _log_request(200, None)
                return {
                    "thought_log": r,
                    "idempotent_replay": True
                }

    # Enforce quotas per workspace per UTC day (accepted think calls / accepted characters)
    # Aggregate from usage_counters for the workspace across api_key_id variants
    total_thoughts = 0
    total_chars = 0
    for r in usage:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != chosen_ws.get("id"):
            continue
        if r.get("window_start") != day_start_iso or r.get("window_end") != day_end_iso:
            continue
        # Count only "accepted think calls" in the window; status doesn't matter for totals here
        tc = r.get("thought_count")
        cc = r.get("char_count")
        if isinstance(tc, int) and tc >= 0:
            total_thoughts += tc
        if isinstance(cc, int) and cc >= 0:
            total_chars += cc

    if total_thoughts + 1 > 10000 or total_chars + len(thought) > 50000000:
        _log_request(429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", quota={"daily_thought_limit": 10000, "daily_char_limit": 50000000})

    # Compute hash
    sha = hashlib.sha256(thought.encode("utf-8")).hexdigest()
    if not re.fullmatch(r"[a-f0-9]{64}", sha):
        _log_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Internal validation failed for thought hash.")

    # Mutations allowed: api_keys.last_used_at, usage_counters, thought_logs insert
    # Update key last_used_at if applicable
    if chosen_key is not None:
        # Ensure key still active/unexpired at write time
        if chosen_key.get("status") != "active":
            _log_request(401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is not active.")
        exp = _parse_dt(chosen_key.get("expires_at"))
        if exp is not None and not (exp > now):
            _log_request(401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is expired.")

        # Persist last_used_at/updated_at
        key_id = chosen_key.get("id")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                break
        _save("api_keys.json", api_keys)

    # Upsert usage counter (workspace + api_key_id + day window)
    ws_id = chosen_ws.get("id")
    ak_id = chosen_key.get("id") if chosen_key else None
    urow = _find_usage_row(ws_id, ak_id)
    if urow is None:
        uid = "uc_" + hashlib.sha256((ws_id + "|" + str(ak_id) + "|" + day_start_iso + "|" + day_end_iso).encode("utf-8")).hexdigest()[:24]
        urow = {
            "id": uid,
            "workspace_id": ws_id,
            "api_key_id": ak_id,
            "window_start": day_start_iso,
            "window_end": day_end_iso,
            "thought_count": 0,
            "char_count": 0,
            "status": "open",
            "created_at": now_iso,
            "updated_at": now_iso
        }
        usage.append(urow)
    # Ensure non-negative ints
    if not isinstance(urow.get("thought_count"), int) or urow["thought_count"] < 0:
        urow["thought_count"] = 0
    if not isinstance(urow.get("char_count"), int) or urow["char_count"] < 0:
        urow["char_count"] = 0
    urow["thought_count"] += 1
    urow["char_count"] += len(thought)
    urow["updated_at"] = now_iso
    _save("usage_counters.json", usage)

    # Insert thought log
    tid = "tl_" + hashlib.sha256((now_iso + "|" + ws_id + "|" + sha).encode("utf-8")).hexdigest()[:24]
    # Ensure uniqueness of id
    existing_ids = {r.get("id") for r in thought_logs if isinstance(r, dict)}
    if tid in existing_ids:
        tid = "tl_" + hashlib.sha256((tid + "|bump").encode("utf-8")).hexdigest()[:24]

    ip_address = _extra.get("ip_address")
    user_agent = _extra.get("user_agent")
    if ip_address is not None and not isinstance(ip_address, str):
        _log_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`ip_address` must be a string when provided.")
    if user_agent is not None and not isinstance(user_agent, str):
        _log_request(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`user_agent` must be a string when provided.")

    row = {
        "id": tid,
        "workspace_id": ws_id,
        "api_key_id": ak_id,
        "thought": thought,
        "thought_sha256": sha,
        "status": "accepted",
        "redacted_reason": None,
        "client_request_id": client_request_id if isinstance(client_request_id, str) else None,
        "ip_address": ip_address,
        "user_agent": user_agent,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    thought_logs.append(row)
    _save("thought_logs.json", thought_logs)

    _log_request(200, None)
    return {"thought_log": row}

def list_workspaces(api_key=None, page=None, page_size=None, status=None, slug=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, hashlib

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validate params
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "`page` must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "`page_size` must be an integer between 1 and 200.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "`status` must be one of: active, suspended, deleted.")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "`slug` must be a string when provided.")
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "`api_key` must be a string when provided.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, str):
            try:
                return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    # Authenticate if api_key is provided (match by id or key_prefix; do NOT check secret_hash)
    chosen_ws_ids = set()
    chosen_key_id = None
    if api_key is not None:
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        matched = None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if api_key not in (k.get("id"), k.get("key_prefix")):
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and not (exp > now_dt):
                continue
            matched = k
            break
        if matched is None:
            # log and reject
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": "req_" + hashlib.sha256((now + "|list_workspaces|unauth|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "list_workspaces",
                "workspace_id": None,
                "api_key_id": None,
                "status": 401,
                "error_code": "UNAUTHORIZED",
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Invalid, revoked, or expired API key.")
        chosen_key_id = matched.get("id")
        chosen_ws_ids.add(matched.get("workspace_id"))
    else:
        # Ambient auth: if there exists at least one active workspace, allow listing all
        any_ws = any(isinstance(w, dict) and isinstance(w.get("id"), str) for w in workspaces)
        if not any_ws:
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": "req_" + hashlib.sha256((now + "|list_workspaces|unauth2|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "list_workspaces",
                "workspace_id": None,
                "api_key_id": None,
                "status": 401,
                "error_code": "UNAUTHORIZED",
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Not authenticated.")

    # Visibility: if api_key provided, only that workspace; else all workspaces
    rows = []
    for w in workspaces:
        if not isinstance(w, dict):
            continue
        if api_key is not None:
            if w.get("id") not in chosen_ws_ids:
                continue
        if status is not None and w.get("status") != status:
            continue
        if slug is not None and w.get("slug") != slug:
            continue
        rows.append(w)

    # Sort stable by created_at then id
    def _sort_key(w):
        ca = w.get("created_at")
        return (ca if isinstance(ca, str) else "", w.get("id") if isinstance(w.get("id"), str) else "")
    rows.sort(key=_sort_key)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # Log request
    latency_ms = int((time.time() - t0) * 1000)
    request_logs.append({
        "id": "req_" + hashlib.sha256((now + "|list_workspaces|" + str(chosen_key_id) + "|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
        "endpoint": "list_workspaces",
        "workspace_id": next(iter(chosen_ws_ids)) if chosen_ws_ids else None,
        "api_key_id": chosen_key_id,
        "status": 200,
        "error_code": None,
        "latency_ms": latency_ms,
        "created_at": now,
    })
    _save("request_logs.json", request_logs)

    return {
        "workspaces": page_rows,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None
    }

def get_workspace(api_key=None, workspace_id=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, hashlib

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    if workspace_id is None or not isinstance(workspace_id, str) or workspace_id == "":
        return _err("VALIDATION_ERROR", "`workspace_id` is required and must be a non-empty string.")
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "`api_key` must be a string when provided.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, str):
            try:
                return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    # Authenticate/authorize
    visible_ws_ids = None  # None means all visible (ambient)
    chosen_key_id = None
    if api_key is not None:
        now_dt = datetime.datetime.now(datetime.timezone.utc)
        matched = None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if api_key not in (k.get("id"), k.get("key_prefix")):
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and not (exp > now_dt):
                continue
            matched = k
            break
        if matched is None:
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": "req_" + hashlib.sha256((now + "|get_workspace|unauth|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "get_workspace",
                "workspace_id": workspace_id,
                "api_key_id": None,
                "status": 401,
                "error_code": "UNAUTHORIZED",
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Invalid, revoked, or expired API key.")
        chosen_key_id = matched.get("id")
        visible_ws_ids = {matched.get("workspace_id")}
    else:
        # Ambient auth: must have at least one workspace in store
        if not any(isinstance(w, dict) and isinstance(w.get("id"), str) for w in workspaces):
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": "req_" + hashlib.sha256((now + "|get_workspace|unauth2|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "get_workspace",
                "workspace_id": workspace_id,
                "api_key_id": None,
                "status": 401,
                "error_code": "UNAUTHORIZED",
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Not authenticated.")

    ws = None
    for w in workspaces:
        if not isinstance(w, dict):
            continue
        if w.get("id") == workspace_id:
            ws = w
            break

    if ws is None or (visible_ws_ids is not None and ws.get("id") not in visible_ws_ids):
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": "req_" + hashlib.sha256((now + "|get_workspace|404|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
            "endpoint": "get_workspace",
            "workspace_id": workspace_id,
            "api_key_id": chosen_key_id,
            "status": 404,
            "error_code": "NOT_FOUND",
            "latency_ms": latency_ms,
            "created_at": now,
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Workspace not found.")

    latency_ms = int((time.time() - t0) * 1000)
    request_logs.append({
        "id": "req_" + hashlib.sha256((now + "|get_workspace|200|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
        "endpoint": "get_workspace",
        "workspace_id": ws.get("id"),
        "api_key_id": chosen_key_id,
        "status": 200,
        "error_code": None,
        "latency_ms": latency_ms,
        "created_at": now,
    })
    _save("request_logs.json", request_logs)

    return {"workspace": ws}

def update_workspace(api_key=None, workspace_id=None, display_name=None, thought_retention_days=None, status=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, hashlib

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    # Validate params
    if workspace_id is None or not isinstance(workspace_id, str) or workspace_id == "":
        return _err("VALIDATION_ERROR", "`workspace_id` is required and must be a non-empty string.")
    if api_key is not None and not isinstance(api_key, str):
        return _err("VALIDATION_ERROR", "`api_key` must be a string when provided.")
    if display_name is not None:
        if not isinstance(display_name, str):
            return _err("VALIDATION_ERROR", "`display_name` must be a string when provided.")
        if len(display_name) < 1 or len(display_name) > 200:
            return _err("VALIDATION_ERROR", "`display_name` length must be between 1 and 200.")
        if display_name == "":
            return _err("VALIDATION_ERROR", "`display_name` must be non-empty.")
    if thought_retention_days is not None:
        if not isinstance(thought_retention_days, int):
            return _err("VALIDATION_ERROR", "`thought_retention_days` must be an integer when provided.")
        if thought_retention_days < 0 or thought_retention_days > 36500:
            return _err("VALIDATION_ERROR", "`thought_retention_days` must be between 0 and 36500.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "`status` must be one of: active, suspended, deleted.")

    if display_name is None and thought_retention_days is None and status is None:
        return _err("VALIDATION_ERROR", "No fields to update.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, str):
            try:
                return datetime.datetime.fromisoformat(x.replace("Z", "+00:00"))
            except Exception:
                return None
        return None

    # Authenticate & permission:
    # If api_key provided: must be active/unexpired, can only update its own workspace.
    # If not provided: ambient auth requires at least one workspace exists, and allows updates (no other ACL defined).
    visible_ws_ids = None
    chosen_key_id = None
    if api_key is not None:
        matched = None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if api_key not in (k.get("id"), k.get("key_prefix")):
                continue
            if k.get("status") != "active":
                continue
            exp = _parse_dt(k.get("expires_at"))
            if exp is not None and not (exp > now_dt):
                continue
            matched = k
            break
        if matched is None:
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": "req_" + hashlib.sha256((now + "|update_workspace|unauth|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "update_workspace",
                "workspace_id": workspace_id,
                "api_key_id": None,
                "status": 401,
                "error_code": "UNAUTHORIZED",
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Invalid, revoked, or expired API key.")
        chosen_key_id = matched.get("id")
        visible_ws_ids = {matched.get("workspace_id")}
    else:
        if not any(isinstance(w, dict) and isinstance(w.get("id"), str) for w in workspaces):
            latency_ms = int((time.time() - t0) * 1000)
            request_logs.append({
                "id": "req_" + hashlib.sha256((now + "|update_workspace|unauth2|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                "endpoint": "update_workspace",
                "workspace_id": workspace_id,
                "api_key_id": None,
                "status": 401,
                "error_code": "UNAUTHORIZED",
                "latency_ms": latency_ms,
                "created_at": now,
            })
            _save("request_logs.json", request_logs)
            return _err("UNAUTHORIZED", "Not authenticated.")

    idx = None
    ws = None
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == workspace_id:
            idx = i
            ws = w
            break

    if ws is None or (visible_ws_ids is not None and ws.get("id") not in visible_ws_ids):
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": "req_" + hashlib.sha256((now + "|update_workspace|404|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
            "endpoint": "update_workspace",
            "workspace_id": workspace_id,
            "api_key_id": chosen_key_id,
            "status": 404,
            "error_code": "NOT_FOUND",
            "latency_ms": latency_ms,
            "created_at": now,
        })
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Workspace not found.")

    # cannot_update_when(status='deleted')
    if ws.get("status") == "deleted":
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": "req_" + hashlib.sha256((now + "|update_workspace|conflict|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
            "endpoint": "update_workspace",
            "workspace_id": workspace_id,
            "api_key_id": chosen_key_id,
            "status": 409,
            "error_code": "CONFLICT",
            "latency_ms": latency_ms,
            "created_at": now,
        })
        _save("request_logs.json", request_logs)
        return _err("CONFLICT", "Cannot update a deleted workspace.")

    # Enforce lifecycle transitions
    if status is not None:
        current = ws.get("status")
        transitions = {
            "active": {"suspended", "deleted"},
            "suspended": {"active", "deleted"},
            "deleted": set()
        }
        if current not in transitions:
            return _err("VALIDATION_ERROR", "Workspace has invalid current status.")
        if status != current:
            if status not in transitions[current]:
                latency_ms = int((time.time() - t0) * 1000)
                request_logs.append({
                    "id": "req_" + hashlib.sha256((now + "|update_workspace|badtrans|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
                    "endpoint": "update_workspace",
                    "workspace_id": workspace_id,
                    "api_key_id": chosen_key_id,
                    "status": 400,
                    "error_code": "INVALID_TRANSITION",
                    "latency_ms": latency_ms,
                    "created_at": now,
                })
                _save("request_logs.json", request_logs)
                return _err("INVALID_TRANSITION", f"Illegal status transition {current!r} -> {status!r}.")
            ws["status"] = status

    # Other constraints
    if display_name is not None:
        if display_name == "":
            return _err("VALIDATION_ERROR", "display_name must be non-empty.")
        ws["display_name"] = display_name
    if thought_retention_days is not None:
        if thought_retention_days < 0:
            return _err("VALIDATION_ERROR", "thought_retention_days must be >= 0.")
        ws["thought_retention_days"] = thought_retention_days

    ws["updated_at"] = now
    workspaces[idx] = ws
    _save("workspaces.json", workspaces)

    latency_ms = int((time.time() - t0) * 1000)
    request_logs.append({
        "id": "req_" + hashlib.sha256((now + "|update_workspace|200|" + str(latency_ms)).encode("utf-8")).hexdigest()[:24],
        "endpoint": "update_workspace",
        "workspace_id": workspace_id,
        "api_key_id": chosen_key_id,
        "status": 200,
        "error_code": None,
        "latency_ms": latency_ms,
        "created_at": now,
    })
    _save("request_logs.json", request_logs)

    return {"workspace": ws}

def create_api_key(workspace_id, name, api_key=None, expires_at=None, **_extra):
    import json, os, datetime, secrets, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return now.isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "expires_at must be an RFC3339 datetime string")
        ss = s.strip()
        if not ss:
            return None, _err("VALIDATION_ERROR", "expires_at must be an RFC3339 datetime string")
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", "expires_at must be an RFC3339 datetime string")

    def _load_list(name):
        d = _load(name)
        return d if isinstance(d, list) else []

    def _save_list(name, rows):
        _save(name, rows)

    def _audit(status, credential_id=None, workspace_id_for_log=None, error_code=None):
        # Observable service dynamics: record every call.
        logs = _load_list("request_logs.json")
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "create_api_key",
            "credential_id": credential_id,
            "workspace_id": workspace_id_for_log,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        })
        _save_list("request_logs.json", logs)

    def _find_workspace(workspaces, wid):
        for w in workspaces:
            if isinstance(w, dict) and w.get("id") == wid:
                return w
        return None

    def _dt_from_iso_maybe(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _key_matches_presented(krow, presented):
        # Authenticate against a client-visible value: allow either the api_keys.id or key_prefix match.
        if not isinstance(presented, str):
            return False
        p = presented.strip()
        if not p:
            return False
        return (krow.get("id") == p) or (krow.get("key_prefix") == p)

    def _is_key_usable(krow):
        if not isinstance(krow, dict):
            return False, "VALIDATION_ERROR"
        if krow.get("status") != "active":
            return False, "UNAUTHORIZED"
        exp = _dt_from_iso_maybe(krow.get("expires_at"))
        if exp is not None and exp <= now:
            return False, "UNAUTHORIZED"
        return True, None

    def _gen_id(prefix):
        return prefix + secrets.token_hex(16)

    # -------- Validate inputs first --------
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _audit("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(name, str):
        _audit("error", None, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a string")
    nm = name.strip()
    if not nm:
        _audit("error", None, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be non-empty")
    if len(nm) > 200:
        _audit("error", None, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be at most 200 characters")

    exp_dt, exp_err = _parse_rfc3339(expires_at)
    if exp_err:
        _audit("error", None, workspace_id, exp_err["error"]["code"])
        return exp_err

    # -------- Load domain data --------
    workspaces = _load_list("workspaces.json")
    api_keys = _load_list("api_keys.json")

    ws = _find_workspace(workspaces, workspace_id.strip())
    if ws is None:
        _audit("error", None, workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found")

    # Business rule: must be in a state that allows key creation.
    if ws.get("status") != "active":
        _audit("error", None, workspace_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active; cannot create API keys unless workspace.status='active'")

    # -------- Authenticate / resolve context --------
    credential_row = None

    if api_key is not None:
        # Explicit credential provided: must authenticate it and ensure it can act on this workspace.
        if not isinstance(api_key, str) or not api_key.strip():
            _audit("error", None, workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string when provided")
        presented = api_key.strip()

        candidates = [k for k in api_keys if isinstance(k, dict) and _key_matches_presented(k, presented)]
        # If there are multiple matches by prefix, prefer one that is usable and belongs to workspace.
        usable = []
        for k in candidates:
            ok, _ = _is_key_usable(k)
            if ok:
                usable.append(k)

        # First require: usable and same workspace
        for k in usable:
            if k.get("workspace_id") == workspace_id:
                credential_row = k
                break

        if credential_row is None:
            # If credential exists but is revoked/expired, reject as unauthorized (no writes).
            for k in candidates:
                ok, _ = _is_key_usable(k)
                if not ok:
                    _audit("error", k.get("id"), workspace_id, "UNAUTHORIZED")
                    return _err("UNAUTHORIZED", "API key is revoked/expired or otherwise not usable")
            # Otherwise: key doesn't belong to this workspace or doesn't exist.
            _audit("error", (candidates[0].get("id") if candidates else None), workspace_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key is not authorized for this workspace")
    else:
        # Ambient auth: choose any usable active key for this workspace, if one exists; otherwise proceed without a key.
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("workspace_id") != workspace_id:
                continue
            ok, _ = _is_key_usable(k)
            if ok:
                credential_row = k
                break

    credential_id = credential_row.get("id") if isinstance(credential_row, dict) else None

    # -------- Enforce constraints for new key --------
    # unique(workspace_id, name)
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") == workspace_id and k.get("name") == nm:
            _audit("error", credential_id, workspace_id, "CONFLICT")
            return _err("CONFLICT", "An API key with this name already exists in the workspace")

    # expires_at is null OR expires_at > created_at (created_at is now)
    if exp_dt is not None and exp_dt <= now:
        _audit("error", credential_id, workspace_id, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "expires_at must be in the future")

    # -------- Create key material --------
    # One-time secret returned; store only a hash.
    # Also ensure unique key_prefix across all keys.
    secret = "thk_" + secrets.token_urlsafe(32)
    secret_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()

    # Generate a unique prefix (10 chars) that doesn't collide.
    existing_prefixes = {k.get("key_prefix") for k in api_keys if isinstance(k, dict)}
    # Use deterministic prefix from secret hash, but iterate if collision (very unlikely).
    prefix_len = 10
    for i in range(1000):
        kp = secret_hash[i:i + prefix_len]
        if len(kp) < prefix_len:
            kp = (secret_hash + secret_hash)[0:prefix_len]
        if kp not in existing_prefixes and kp:
            key_prefix = kp
            break
    else:
        _audit("error", credential_id, workspace_id, "CONFLICT")
        return _err("CONFLICT", "Could not allocate a unique key_prefix")

    new_id = _gen_id("thk_key_")

    created_at = _now_iso()
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "name": nm,
        "key_prefix": key_prefix,
        "secret_hash": secret_hash,
        "status": "active",
        "last_used_at": None,
        "expires_at": exp_dt.isoformat().replace("+00:00", "Z") if exp_dt is not None else None,
        "created_at": created_at,
        "updated_at": created_at,
    }

    # Persist mutation
    api_keys.append(row)
    _save_list("api_keys.json", api_keys)

    # If authenticated via an existing key, update its last_used_at (allowed side effect).
    if isinstance(credential_row, dict):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == credential_row.get("id"):
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                break
        _save_list("api_keys.json", api_keys)

    _audit("success", credential_id, workspace_id, None)

    # Return key record + one-time secret. Never fabricate fields outside schema.
    return {
        "api_key": row,
        "secret": secret
    }

def update_api_key(api_key_id, api_key=None, name=None, expires_at=None, status=None, **_extra):
    import json, os, datetime, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None: return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "expires_at must be a RFC3339 datetime string")
        ss = s.strip()
        if not ss:
            return None, _err("VALIDATION_ERROR", "expires_at must be a RFC3339 datetime string")
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", "expires_at must be a RFC3339 datetime string")

    def _audit(status_s, credential_id=None, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "update_api_key",
            "credential_id": credential_id,
            "workspace_id": workspace_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    def _find_auth_key(presented):
        if presented is None:
            return None
        if not isinstance(presented, str) or not presented.strip():
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string"), None
        presented = presented.strip()
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                return None, k
        return _err("UNAUTHORIZED", "Invalid API key"), None

    if not isinstance(api_key_id, str) or not api_key_id.strip():
        _audit("error", None, None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")

    if name is not None:
        if not isinstance(name, str) or not name.strip():
            _audit("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a non-empty string")
        if len(name) > 200:
            _audit("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be at most 200 characters")

    if status is not None:
        if status not in ("active", "revoked", "expired"):
            _audit("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status")

    exp_dt, exp_err = _parse_rfc3339(expires_at)
    if exp_err:
        _audit("error", None, None, exp_err["error"]["code"])
        return exp_err

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []

    idx = None
    for i, k in enumerate(keys):
        if k.get("id") == api_key_id:
            idx = i
            break
    if idx is None:
        _audit("error", None, None, "NOT_FOUND")
        return _err("NOT_FOUND", "API key not found")
    key_row = keys[idx]
    workspace_id = key_row.get("workspace_id")

    # Optional authentication: if provided, must be active/unexpired and same workspace
    auth_err, auth_key = _find_auth_key(api_key)
    if auth_err:
        _audit("error", None, workspace_id, auth_err["error"]["code"])
        return auth_err
    credential_id = auth_key.get("id") if auth_key else None
    if auth_key:
        if auth_key.get("status") != "active":
            _audit("error", credential_id, workspace_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not active")
        kexp = auth_key.get("expires_at")
        if kexp:
            kexp_dt, kexp_e = _parse_rfc3339(kexp)
            if kexp_e:
                _audit("error", credential_id, workspace_id, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "API key has invalid expiry on record")
            if not (kexp_dt > now):
                _audit("error", credential_id, workspace_id, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "API key expired")
        if auth_key.get("workspace_id") != workspace_id:
            _audit("error", credential_id, workspace_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key not authorized for this workspace")

    # Workspace must exist and be active for updates? Schema doesn't say, but access/state may matter.
    # We'll enforce cannot operate if workspace deleted/suspended as "UNAUTHORIZED" (service-level).
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        _audit("error", credential_id, workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "Workspace not found for API key")
    if ws.get("status") != "active":
        _audit("error", credential_id, workspace_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace not active", workspace_status=ws.get("status"))

    # CONFLICT if trying to change a revoked/expired key.
    current_status = key_row.get("status")
    is_mutation = any(v is not None for v in (name, expires_at, status))
    if is_mutation and current_status in ("revoked", "expired"):
        _audit("error", credential_id, workspace_id, "CONFLICT")
        return _err("CONFLICT", "Cannot modify a revoked or expired API key", status=current_status)

    # Apply updates with validation
    changed = False

    if name is not None and name != key_row.get("name"):
        # Unique(workspace_id, name)
        if any(k.get("workspace_id") == workspace_id and k.get("name") == name and k.get("id") != api_key_id for k in keys):
            _audit("error", credential_id, workspace_id, "CONFLICT")
            return _err("CONFLICT", "API key name already exists in this workspace")
        key_row["name"] = name
        changed = True

    if expires_at is not None:
        # expires_at must be > created_at (stored string)
        created_at_s = key_row.get("created_at")
        created_dt, created_err = _parse_rfc3339(created_at_s) if isinstance(created_at_s, str) else (None, _err("VALIDATION_ERROR", "Invalid created_at on record"))
        if created_err:
            _audit("error", credential_id, workspace_id, "CONFLICT")
            return _err("CONFLICT", "Corrupt API key record (created_at)")
        if not (exp_dt > created_dt):
            _audit("error", credential_id, workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "expires_at must be after created_at")

        # cannot_set_active_if(expires_at <= now())
        if key_row.get("status") == "active" and not (exp_dt > now):
            _audit("error", credential_id, workspace_id, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cannot set expires_at in the past for an active key")
        key_row["expires_at"] = _iso(exp_dt)
        changed = True

        # If expires_at is now/past, the key cannot remain active; require explicit transition.
        if key_row.get("status") == "active" and not (exp_dt > now):
            _audit("error", credential_id, workspace_id, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Active key cannot have expires_at <= now() without expiring it")

    if status is not None and status != current_status:
        # Allowed transitions: active -> revoked/expired only (per tool description)
        if current_status != "active":
            _audit("error", credential_id, workspace_id, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Invalid transition from {current_status} to {status}")
        if status not in ("revoked", "expired"):
            _audit("error", credential_id, workspace_id, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", f"Invalid transition from active to {status}")

        if status == "active":
            _audit("error", credential_id, workspace_id, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot transition to active")

        if status == "expired":
            # If expiring explicitly, allow regardless of expires_at
            key_row["status"] = "expired"
            changed = True
        elif status == "revoked":
            key_row["status"] = "revoked"
            changed = True

    if not changed:
        _audit("error", credential_id, workspace_id, "NOT_FOUND")
        return _err("NOT_FOUND", "No changes applied")

    key_row["updated_at"] = _iso(now)
    keys[idx] = key_row
    _save("api_keys.json", keys)

    # Never return secret
    out = dict(key_row)
    _audit("ok", credential_id, workspace_id, None)
    return {"api_key": out}

def whoami(api_key=None, **_extra):
    import json, os, datetime, secrets, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0182000" if __import__("os").path.isdir("./environment_mix/0182000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None: return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", "datetime must be a RFC3339 string")
        ss = s.strip()
        if not ss:
            return None, _err("VALIDATION_ERROR", "datetime must be a RFC3339 string")
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", "datetime must be a RFC3339 string")

    def _audit(status_s, credential_id=None, workspace_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + secrets.token_hex(12),
            "endpoint": "whoami",
            "credential_id": credential_id,
            "workspace_id": workspace_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        })
        _save("request_logs.json", logs)

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    usage = _load("usage_counters.json")
    if not isinstance(usage, list):
        usage = []

    credential = None
    if api_key is not None:
        if not isinstance(api_key, str) or not api_key.strip():
            _audit("error", None, None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
        presented = api_key.strip()
        for k in keys:
            if k.get("id") == presented or k.get("key_prefix") == presented:
                credential = k
                break
        if not credential:
            _audit("error", None, None, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Invalid API key")
    else:
        # Ambient auth: choose any valid active/unexpired key in an active workspace.
        for k in keys:
            if k.get("status") != "active":
                continue
            ws = next((w for w in workspaces if w.get("id") == k.get("workspace_id")), None)
            if not ws or ws.get("status") != "active":
                continue
            kexp = k.get("expires_at")
            if kexp:
                kexp_dt, kexp_err = _parse_rfc3339(kexp)
                if kexp_err:
                    continue
                if not (kexp_dt > now):
                    continue
            credential = k
            break
        if not credential:
            # If no key exists, fall back to an active workspace identity (no credential).
            ws = next((w for w in workspaces if w.get("status") == "active"), None)
            if not ws:
                _audit("error", None, None, "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "No active identity available")
            # Compute quota using workspace-only counters (api_key_id null).
            ws_id = ws.get("id")
            # window: UTC day
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            day_end = day_start + datetime.timedelta(days=1)
            day_start_s = _iso(day_start)
            day_end_s = _iso(day_end)
            ctr = next((c for c in usage if c.get("workspace_id") == ws_id and c.get("api_key_id") is None and c.get("window_start") == day_start_s and c.get("window_end") == day_end_s), None)
            thought_count = int(ctr.get("thought_count")) if ctr and isinstance(ctr.get("thought_count"), int) else 0
            char_count = int(ctr.get("char_count")) if ctr and isinstance(ctr.get("char_count"), int) else 0
            _audit("ok", None, ws_id, None)
            return {
                "identity": {
                    "type": "workspace",
                    "workspace": ws,
                    "api_key": None,
                },
                "scopes": ["think:write", "keys:read", "keys:write"],
                "quota": {
                    "window": {"start": day_start_s, "end": day_end_s},
                    "limits": {"thoughts_per_day": 10000, "chars_per_day": 50000000},
                    "usage": {"thought_count": thought_count, "char_count": char_count},
                    "remaining": {
                        "thought_count": max(0, 10000 - thought_count),
                        "char_count": max(0, 50000000 - char_count),
                    },
                },
            }

    credential_id = credential.get("id")
    ws_id = credential.get("workspace_id")
    ws = next((w for w in workspaces if w.get("id") == ws_id), None)
    if not ws:
        _audit("error", credential_id, ws_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace not found")

    # Credential validity
    if credential.get("status") != "active":
        _audit("error", credential_id, ws_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key not active")
    kexp = credential.get("expires_at")
    if kexp:
        kexp_dt, kexp_err = _parse_rfc3339(kexp)
        if kexp_err:
            _audit("error", credential_id, ws_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key has invalid expiry on record")
        if not (kexp_dt > now):
            _audit("error", credential_id, ws_id, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "API key expired")

    if ws.get("status") != "active":
        _audit("error", credential_id, ws_id, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace not active", workspace_status=ws.get("status"))

    # Compute quota window (UTC day) and usage for this workspace aggregated (api_key_id null) plus per-key
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    day_end = day_start + datetime.timedelta(days=1)
    day_start_s = _iso(day_start)
    day_end_s = _iso(day_end)

    ws_ctr = next((c for c in usage if c.get("workspace_id") == ws_id and c.get("api_key_id") is None and c.get("window_start") == day_start_s and c.get("window_end") == day_end_s), None)
    ws_thought_count = int(ws_ctr.get("thought_count")) if ws_ctr and isinstance(ws_ctr.get("thought_count"), int) else 0
    ws_char_count = int(ws_ctr.get("char_count")) if ws_ctr and isinstance(ws_ctr.get("char_count"), int) else 0

    key_ctr = next((c for c in usage if c.get("workspace_id") == ws_id and c.get("api_key_id") == credential_id and c.get("window_start") == day_start_s and c.get("window_end") == day_end_s), None)
    key_thought_count = int(key_ctr.get("thought_count")) if key_ctr and isinstance(key_ctr.get("thought_count"), int) else 0
    key_char_count = int(key_ctr.get("char_count")) if key_ctr and isinstance(key_ctr.get("char_count"), int) else 0

    _audit("ok", credential_id, ws_id, None)
    return {
        "identity": {
            "type": "api_key",
            "workspace": ws,
            "api_key": {
                "id": credential.get("id"),
                "workspace_id": credential.get("workspace_id"),
                "name": credential.get("name"),
                "key_prefix": credential.get("key_prefix"),
                "status": credential.get("status"),
                "last_used_at": credential.get("last_used_at"),
                "expires_at": credential.get("expires_at"),
                "created_at": credential.get("created_at"),
                "updated_at": credential.get("updated_at"),
            },
        },
        "scopes": ["think:write", "keys:read", "keys:write"],
        "quota": {
            "window": {"start": day_start_s, "end": day_end_s},
            "limits": {"thoughts_per_day": 10000, "chars_per_day": 50000000},
            "workspace_usage": {"thought_count": ws_thought_count, "char_count": ws_char_count},
            "api_key_usage": {"thought_count": key_thought_count, "char_count": key_char_count},
            "remaining": {
                "thought_count": max(0, 10000 - ws_thought_count),
                "char_count": max(0, 50000000 - ws_char_count),
            },
        },
    }
